/** Persisted order record. */
export interface Order {
  id: string;
  total: number;
}

/** Prefix of the message raised when a requested identifier has no stored order. */
export const MESSAGE_ORDER_NOT_FOUND_PREFIX = "order not found: ";

/**
 * Data access contract used by {@link loadOrders}.
 *
 * @remarks Implementations must resolve a whole identifier batch in one round
 * trip; a per-identifier implementation reintroduces the N+1 access pattern.
 */
export interface OrderStore {
  /**
   * Looks up several orders in a single query.
   *
   * @param ids - Order identifiers to resolve, possibly with duplicates.
   * @returns The orders that exist for `ids`; unknown identifiers are omitted.
   */
  findByIds(ids: string[]): Promise<Order[]>;
}

/**
 * Loads orders by identifier while preserving the requested order.
 *
 * @param store - Order data store.
 * @param ids - Order identifiers in the desired output order; duplicates are
 * repeated in the output.
 * @returns The resolved orders, one per requested identifier.
 * @throws Error when an identifier does not resolve. The reported identifier is
 * the first unresolved one in `ids`.
 * @remarks Performs at most one store query per call, including zero queries
 * when `ids` is empty.
 */
export async function loadOrders(store: OrderStore, ids: string[]): Promise<Order[]> {
  if (ids.length === 0) {
    return [];
  }

  const ordersById = new Map<string, Order>();
  for (const order of await store.findByIds(ids)) {
    ordersById.set(order.id, order);
  }

  const orders: Order[] = [];
  for (const id of ids) {
    const order = ordersById.get(id);
    if (!order) {
      throw new Error(`${MESSAGE_ORDER_NOT_FOUND_PREFIX}${id}`);
    }
    orders.push(order);
  }
  return orders;
}
