import { test } from "node:test";
import assert from "node:assert/strict";

import { validateCreateUser } from "./validation.js";
import { lineTotal, orderTotal } from "./pricing.js";
import {
  loadOrders,
  MESSAGE_ORDER_NOT_FOUND_PREFIX,
  type Order,
  type OrderStore,
} from "./repository.js";
import { resolveUserFile, BASE_DIR } from "./files.js";

/** Upper bound on store round trips allowed for a single {@link loadOrders} call. */
const MAX_QUERIES_PER_REQUEST = 1;
const FIRST_ORDER_ID = "a";
const SECOND_ORDER_ID = "b";
const MISSING_ORDER_ID = "missing";
const ALSO_MISSING_ORDER_ID = "also-missing";

/** Store plus the identifier batches it received, in call order. */
interface RecordingStore {
  store: OrderStore;
  batches: string[][];
}

/**
 * Builds an {@link OrderStore} backed by `orders` that records every batch.
 *
 * @param orders - Orders the store can resolve.
 * @returns The recording store and the batches it received.
 */
function createRecordingStore(orders: Order[]): RecordingStore {
  const ordersById = new Map(orders.map((order) => [order.id, order]));
  const batches: string[][] = [];
  const store: OrderStore = {
    async findByIds(ids) {
      batches.push([...ids]);
      return ids.flatMap((id) => {
        const order = ordersById.get(id);
        return order ? [order] : [];
      });
    },
  };
  return { store, batches };
}

/**
 * Wraps `store` so the test fails when `loadOrders` issues more than
 * {@link MAX_QUERIES_PER_REQUEST} query.
 *
 * @param store - Store to guard.
 * @returns The guarded store and a function returning the observed query count.
 */
function guardQueryCount(store: OrderStore): { store: OrderStore; queryCount: () => number } {
  let queries = 0;
  return {
    store: {
      async findByIds(ids) {
        queries += 1;
        if (queries > MAX_QUERIES_PER_REQUEST) {
          throw new Error(`query budget exceeded: ${queries} queries for one request`);
        }
        return store.findByIds(ids);
      },
    },
    queryCount: () => queries,
  };
}

test("validates a valid user", () => {
  assert.deepEqual(validateCreateUser({ email: "a@b.co", name: "Ada", age: 30 }), {
    ok: true,
    errors: [],
  });
});

test("rejects a missing email", () => {
  const result = validateCreateUser({ name: "Ada" });
  assert.equal(result.ok, false);
  assert.match(result.errors.join(","), /email/);
});

test("prices taxable and non-taxable items", () => {
  assert.equal(lineTotal({ unitPrice: 10, quantity: 2, taxable: false }), 20);
  assert.equal(lineTotal({ unitPrice: 10, quantity: 2, taxable: true }), 24);
});

test("totals an order", () => {
  assert.equal(
    orderTotal([
      { unitPrice: 10, quantity: 1, taxable: false },
      { unitPrice: 5, quantity: 2, taxable: true },
    ]),
    22,
  );
});

test("loads orders in order", async () => {
  const { store } = createRecordingStore([
    { id: FIRST_ORDER_ID, total: 1 },
    { id: SECOND_ORDER_ID, total: 2 },
  ]);
  const orders = await loadOrders(store, [SECOND_ORDER_ID, FIRST_ORDER_ID]);
  assert.deepEqual(orders.map((o) => o.id), [SECOND_ORDER_ID, FIRST_ORDER_ID]);
});

test("loads orders with one query per request", async () => {
  const requestedIds = [FIRST_ORDER_ID, SECOND_ORDER_ID, "c", "d", "e"];
  const { store: recordingStore, batches } = createRecordingStore(
    requestedIds.map((id, index) => ({ id, total: index })),
  );
  const { store, queryCount } = guardQueryCount(recordingStore);

  const orders = await loadOrders(store, requestedIds);

  assert.deepEqual(orders.map((o) => o.id), requestedIds);
  assert.equal(queryCount(), MAX_QUERIES_PER_REQUEST);
  assert.equal(batches.length, MAX_QUERIES_PER_REQUEST);
  assert.deepEqual([...batches[0]!].sort(), [...requestedIds].sort());
});

test("repeats duplicated identifiers without extra queries", async () => {
  const { store: recordingStore, batches } = createRecordingStore([
    { id: FIRST_ORDER_ID, total: 1 },
  ]);
  const { store, queryCount } = guardQueryCount(recordingStore);

  const orders = await loadOrders(store, [FIRST_ORDER_ID, FIRST_ORDER_ID]);

  assert.deepEqual(orders.map((o) => o.id), [FIRST_ORDER_ID, FIRST_ORDER_ID]);
  assert.equal(queryCount(), MAX_QUERIES_PER_REQUEST);
  assert.equal(batches.length, MAX_QUERIES_PER_REQUEST);
});

test("throws for the first unresolved identifier in request order", async () => {
  const { store } = createRecordingStore([{ id: FIRST_ORDER_ID, total: 1 }]);

  await assert.rejects(
    loadOrders(store, [FIRST_ORDER_ID, MISSING_ORDER_ID, ALSO_MISSING_ORDER_ID]),
    { name: "Error", message: `${MESSAGE_ORDER_NOT_FOUND_PREFIX}${MISSING_ORDER_ID}` },
  );
});

test("queries nothing for an empty identifier list", async () => {
  const { store: recordingStore, batches } = createRecordingStore([]);
  const { store, queryCount } = guardQueryCount(recordingStore);

  const orders = await loadOrders(store, []);

  assert.deepEqual(orders, []);
  assert.equal(queryCount(), 0);
  assert.deepEqual(batches, []);
});

test("resolves a normal file name", () => {
  assert.equal(resolveUserFile("avatar.png"), `${BASE_DIR}/avatar.png`);
});
EOF
